#!/usr/bin/env python3
"""Generate the Worker historical adapter from the same validated Python input."""
from pathlib import Path
import json
import sys
ROOT = Path(__file__).resolve().parents[1]
sys.path.insert(0, str(ROOT))
from reviewed_history import fetch_history

records = fetch_history()
(ROOT / "worker/reviewed-history.mjs").write_text(
    "// Generated by scripts/build_reviewed_history.py; Church of Malware / saviorSEC.\n"
    "export const historicalMilestones = " + json.dumps(records, ensure_ascii=False, indent=2) + ";\n")
print(f"Validated {len(records)} historical milestones.")
